mapper.update:
UPDATE app_user SET locked_until=#{lockedUntil},version=version+1,
    updated_by=#{operator},updated_at=#{now}
WHERE user_id=#{userId} AND (locked_until IS NULL OR locked_until < #{lockedUntil})

UPDATE app_user SET locked_until=NULL,version=version+1,
    updated_by=#{operator},updated_at=#{now}
WHERE user_id=#{userId} AND locked_until IS NOT NULL AND locked_until <= #{now}
